use vstd::prelude::*;

verus! {

spec fn count_eligible(participations: Seq<int>, k: int) -> int {
    // Count how many participants have attendance_count such that 5 - attendance_count >= k
    // Participation counts between 0..=5, k between 0..=5 
    participations.iter()
        .filter(|&x| 0 <= x && x <= 5 && 5 - x >= k)
        .count() as int
}

fn solve(n: u8, k: u8, participations: Vec<u8>) -> u8
    requires
        k <= 5,
    ensures
        // Result is (number of eligible participants in the first n elements) / 3
        let eligible = count_eligible(
            // Convert vec elements to int and restrict length to n elements or length of participations
            Seq::<int>::from_iter(participations.iter().map(|x| *x as int).take(n as usize)), 
            k as int
        );
        && result == (eligible / 3) as u8,
{
    // We only consider up to n participants from the vector
    let mut eligible_count: u8 = 0;
    let len = (participations.len() as u8).min(n);
    let mut i: u8 = 0;
    while i < len
        invariant
            i <= len,
            eligible_count as int == count_eligible(
                Seq::<int>::from_iter(participations.iter().map(|x| *x as int).take(i as usize)),
                k as int
            ),
        decreases len - i,
    {
        let attendance = participations[i as usize];
        if 5 - attendance >= k {
            eligible_count = eligible_count + 1;
        }
        i = i + 1;
    }
    // number of teams is eligible_count / 3 (integer division)
    eligible_count / 3
}

} // end verus module

